#include <iostream>
#include <map>
#include <string>
int main() {
    std::map<std::string, int> m;
    m["carol"] = 88;
    m["alice"] = 90;
    m["bob"] = 75;
    for (auto& kv : m) std::cout << kv.first << '=' << kv.second << ' ';
    std::cout << '\n';
    auto it = m.find("bob");
    std::cout << (it != m.end() ? "found" : "miss") << ' ' << it->second << '\n';
}
